begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(12);
insert into auth.users(id,email) values('e1060000-0000-4000-8000-000000000001','e1-customer@example.invalid'),('e1060000-0000-4000-8000-000000000002','e1-customer2@example.invalid');
insert into public.admin_profiles(user_id,role) values('e1060000-0000-4000-8000-000000000001','operator'),('e1060000-0000-4000-8000-000000000002','operator');
insert into auth.sessions(id,user_id,created_at,updated_at,aal) values('e1060000-0000-4000-8000-000000000011','e1060000-0000-4000-8000-000000000001',now(),now(),'aal1'),('e1060000-0000-4000-8000-000000000012','e1060000-0000-4000-8000-000000000002',now(),now(),'aal1');
set local role authenticated;
set local request.jwt.claim.sub='e1060000-0000-4000-8000-000000000001';
set local request.jwt.claims='{"sub":"e1060000-0000-4000-8000-000000000001","session_id":"e1060000-0000-4000-8000-000000000011","aal":"aal1"}';
select is(public.create_evalia_customer('QA E1 primero','70000109','pickup',null,'e1060000-0000-4000-8000-000000000021',false)->>'state','created','operador puede registrar');
select is(public.create_evalia_customer('QA E1 primero','70000109','pickup',null,'e1060000-0000-4000-8000-000000000021',false)->>'id',(select id::text from public.customers where name='QA E1 primero'),'mismo request devuelve mismo ID');
select is((select count(*) from public.customers where name='QA E1 primero'),1::bigint,'un solo registro');
select throws_ok($$select public.create_evalia_customer('QA E1 cambio','70000109','pickup',null,'e1060000-0000-4000-8000-000000000021',false)$$,'23505',null,'request cambiado se rechaza');
select is(public.create_evalia_customer('QA E1 segundo','+591 7000-0109','pickup',null,'e1060000-0000-4000-8000-000000000022',false)->>'state','duplicate','normaliza prefijo y formato');
select is((select count(*) from public.customers where name='QA E1 segundo'),0::bigint,'advertencia no inserta');
select is(public.create_evalia_customer('QA E1 segundo','+591 7000-0109','pickup',null,'e1060000-0000-4000-8000-000000000022',true)->>'state','created','duplicado explícitamente permitido');
select is((select count(*) from public.customers where name like 'QA E1 %'),2::bigint,'dos fichas independientes');
select is(public.create_evalia_customer('QA E1 tercero','0059170000109','shipping','La Paz','e1060000-0000-4000-8000-000000000023',false)->>'count','2','detecta ambas fichas');
select throws_ok($$select public.create_evalia_customer('QA E1 envío','70000110','shipping','','e1060000-0000-4000-8000-000000000024',true)$$,'22023',null,'envío sin destino rechazado');
set local request.jwt.claim.sub='e1060000-0000-4000-8000-000000000002';
set local request.jwt.claims='{"sub":"e1060000-0000-4000-8000-000000000002","session_id":"e1060000-0000-4000-8000-000000000012","aal":"aal1"}';
select throws_ok($$select public.create_evalia_customer('QA E1 primero','70000109','pickup',null,'e1060000-0000-4000-8000-000000000021',false)$$,'23505',null,'otro actor no reutiliza request');
reset role;
select ok(not has_table_privilege('authenticated','evalia_security.customer_create_requests','SELECT'),'ledger privado');
select * from finish();
rollback;
